(window.webpackJsonp=window.webpackJsonp||[]).push([[478],{809:function(t,r,e){"use strict";e.r(r);var a=e(33),s=Object(a.a)({},function(){var t=this,r=t.$createElement,e=t._self._c||r;return e("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[e("h1",{attrs:{id:"indelning-av-rostfria-stal-austenitiska-stal"}},[e("a",{staticClass:"header-anchor",attrs:{href:"#indelning-av-rostfria-stal-austenitiska-stal","aria-hidden":"true"}},[t._v("#")]),t._v(" Indelning av rostfria stål - Austenitiska stål")]),t._v(" "),e("p",[t._v("De austenitiska stålen används ofta i våt miljö allt från 18Cr7Ni till 27Cr31Ni4Mo eller ännu högre legerade.")]),t._v(" "),e("p",[t._v("Med ökande krom- och molybden halter blir stålen beständiga mot allt mer aggressiva korrosiva angrepp. Det gäller framför allt allmänkorrosion, spaltkorrosion och punktfrätning. Resistensen mot punkt- och spaltangrepp är viktig då stålen ofta används i kloridhaltig miljö. Användning i havsvatten eller i cellulosaindustri är vanlig.")]),t._v(" "),e("p",[t._v("Svetsbarheten för de austenitiska stålen är mycket god, då HAZ ej försprödas som i t ex ferritiska stål. Värmetillförseln bör dock hållas låg, särskilt för de högre legerade austeniterna. En tumregel att följa är max 1,0 kJ/mm i värmetillförsel och en mellansträngstemperatur av högst 150 °C. Austenitiska stål med högre kolhalt, t.ex. X5CrNi1810 kan urskilja korngränskarbider i den värmepåverkande zonen, vilket kan förorsaka interkristallin korrosion (korngränsfrätning) i sura miljöer. För att motverka detta har de lågkolhaltiga stålen utvecklats.")]),t._v(" "),e("p",[t._v("Ett annat sätt att lösa detta problem på är att legera stålen med niob eller titan vilka tar hand om kolet snabbare än kromet och på så sätt förhindrar att kromkarbider utskiljs i korngränserna. De moderna höglegerade austenitiska stålen för våt, korrosiv miljö har nästa undantagslöst en låg kolhalt, < 0,025 %.")]),t._v(" "),e("p",[t._v("Tillsatsmaterialen för de austenitiska stålen är i princip artegna, fast något överlegerade för att kompensera för segringar etc. Stålen upp till ungefär legeringsnivå X2CrNiMo18-15-4 har tillsatsmaterial som ger 5– 10 % ferrit i svetsgodset.")]),t._v(" "),e("p",[t._v("Detta för att försäkra sig om ett primärt ferritiskt stelnande av svetsgodset, vilket är gynnsamt ur varmsprickssäkerhetssynpunkt.")]),t._v(" "),e("p",[t._v("De höglegerade austeniternas svetsgods är också känsliga för återuppvärmning vilket ger ytterligare anledning till att vara försiktig med värmetillförseln vid flersträngssvetsning.")]),t._v(" "),e("img",{attrs:{alt:"",height:"186",src:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Intergranular_corrosion.JPG/768px-Intergranular_corrosion.JPG",width:"240"}}),t._v(" "),e("p",[t._v("Kromkarbider tillsammans med dragspänningar kan leda till interkristallinska spänningssprickor")]),t._v(" "),e("img",{attrs:{alt:"",src:"https://lernia.itslearning.com/data/1821/C34377/Pss1/pss1-2.png"}}),t._v(" "),e("p",[t._v("Kromkarbider bildas när austenitkornen uppvärms mellan 600-900 grader. Detta kallas för sensibilisering.")])])},[],!1,null,null,null);r.default=s.exports}}]);